        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .metadata li {
        border: 1px solid var(--border);
        border-radius: 999px;
        padding: 0.45rem 0.75rem;
        background: var(--surface-muted);
        color: #475467;
        font-size: 0.9rem;
      }

      .actions,
      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      button {
        min-height: 44px;
        border: 0;
        border-radius: 999px;
        padding: 0.75rem 1.1rem;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition:
          background-color 160ms ease,
          box-shadow 160ms ease,
          color 160ms ease,
          transform 160ms ease;
      }

      button:focus-visible {
        outline: 3px solid rgba(49, 87, 213, 0.32);
        outline-offset: 3px;
      }

      button:hover {
        transform: translateY(-1px);
      }

      .button-secondary {
        border: 1px solid var(--border);
        background: var(--surface);
        color: var(--text);
      }

      .trigger,
      .button-danger {
        background: var(--danger);
        color: #ffffff;
        box-shadow: 0 12px 24px rgba(217, 45, 32, 0.22);
