        width: min(calc(100vw - 2rem), 440px);
        border: 0;
        border-radius: 24px;
        padding: 0;
        background: var(--surface);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.58);
        backdrop-filter: blur(6px);
      }

      .dialog-content {
        padding: 1.5rem;
      }

      .warning-icon {
        display: grid;
        width: 48px;
        height: 48px;
        margin-bottom: 1rem;
        place-items: center;
        border-radius: 50%;
        background: #fee4e2;
        color: var(--danger);
        font-size: 1.35rem;
        font-weight: 800;
      }

      .dialog-content h2 {
        margin-bottom: 0.5rem;
        font-size: 1.35rem;
      }

      .dialog-actions {
        justify-content: flex-end;
        margin-top: 1.5rem;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        font-weight: 700;
        color: var(--danger-dark);
      }

      @media (max-width: 560px) {
        main {
          width: min(100% - 1rem, 720px);
        }

        .content,
        .dialog-content {
          padding: 1.15rem;
        }

        .actions button,
        .dialog-actions button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main>
      <section class="preview-card" aria-labelledby="page-title">
        <div class="image-frame">
          <img
            src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 750'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop stop-color='%2398b8ff'/%3E%3Cstop offset='1' stop-color='%23f9d2b4'/%3E%3C/linearGradient%3E%3ClinearGradient id='hill' x1='0' x2='1'%3E%3Cstop stop-color='%232d6a4f'/%3E%3Cstop offset='1' stop-color='%2374c69d'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1200' height='750' fill='url(%23sky)'/%3E%3Ccircle cx='930' cy='160' r='86' fill='%23fff3b0'/%3E%3Cpath d='M0 560 C190 420 330 480 480 390 C640 292 770 440 940 344 C1060 276 1130 320 1200 292 V750 H0 Z' fill='%231f3b63' opacity='.82'/%3E%3Cpath d='M0 620 C220 512 390 608 570 510 C760 408 925 548 1200 430 V750 H0 Z' fill='url(%23hill)'/%3E%3Cpath d='M650 232 L720 360 H585 Z' fill='%23ffffff' opacity='.78'/%3E%3C/svg%3E"
            alt="Landscape illustration with rolling green hills and a warm sky"
          >
        </div>

        <div class="content">
          <div>
            <p class="eyebrow">Library preview</p>
            <h1 id="page-title">Mountain sunrise</h1>
            <p>
              Review this image before making changes to your library. Deleting
              it removes the image from your saved collection.
            </p>
          </div>

          <ul class="metadata" aria-label="Image details">
            <li>PNG</li>
            <li>4.2 MB</li>
            <li>Added today</li>
          </ul>

          <div class="actions">
            <button class="trigger" type="button">Delete image</button>
            <button class="button-secondary" type="button">Download</button>
          </div>

          <p class="status" role="status" aria-live="polite"></p>
        </div>
      </section>
    </main>

    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <div class="dialog-content">
        <div class="warning-icon" aria-hidden="true">!</div>
        <h2 id="dialog-title">Delete this image?</h2>
        <p id="dialog-description">
          This action will remove “Mountain sunrise” from your library. You can
          upload it again later, but it will no longer appear in your saved images.
        </p>
        <div class="dialog-actions">
          <button class="button-secondary" type="button" data-close-dialog>Cancel</button>
          <button class="button-danger" type="button" data-confirm-delete>Delete image</button>
        </div>
      </div>
    </dialog>

    <script>
      const deleteDialog = document.querySelector("#delete-dialog");
      const openDialogButton = document.querySelector(".trigger");
      const closeDialogButton = document.querySelector("[data-close-dialog]");
      const confirmDeleteButton = document.querySelector("[data-confirm-delete]");
      const statusMessage = document.querySelector(".status");

      openDialogButton.addEventListener("click", () => {
        deleteDialog.showModal();
      });

      closeDialogButton.addEventListener("click", () => {
        deleteDialog.close();
      });

      confirmDeleteButton.addEventListener("click", () => {
        statusMessage.textContent = "Mountain sunrise was deleted from your library.";
        deleteDialog.close();
        openDialogButton.disabled = true;
        openDialogButton.textContent = "Image deleted";
      });

      deleteDialog.addEventListener("click", (event) => {
        if (event.target === deleteDialog) {
          deleteDialog.close();
        }
      });
    </script>
  </body>
