        margin: 0 0 0.35rem;
        color: var(--primary);
        font-size: 0.78rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        margin-top: 0;
      }

      h1 {
        margin-bottom: 0.45rem;
        font-size: clamp(1.75rem, 5vw, 2.4rem);
        line-height: 1.05;
      }

      p {
        color: var(--muted);
        line-height: 1.6;
      }

