        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .metadata li {
        border: 1px solid var(--border);
        border-radius: 999px;
        padding: 0.45rem 0.75rem;
        background: var(--surface-muted);
        color: #475467;
        font-size: 0.9rem;
      }

      .actions,
      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      button {
        min-height: 44px;
        border: 0;
        border-radius: 999px;
        padding: 0.75rem 1.1rem;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition:
          background-color 160ms ease,
          box-shadow 160ms ease,
          color 160ms ease,
          transform 160ms ease;
      }

      button:focus-visible {
        outline: 3px solid rgba(49, 87, 213, 0.32);
        outline-offset: 3px;
      }

      button:hover {
        transform: translateY(-1px);
      }

      .button-secondary {
        border: 1px solid var(--border);
        background: var(--surface);
        color: var(--text);
      }

      .trigger,
      .button-danger {
        background: var(--danger);
        color: #ffffff;
        box-shadow: 0 12px 24px rgba(217, 45, 32, 0.22);
      }

      .trigger:hover,
      .button-danger:hover {
        background: var(--danger-dark);
      }

      dialog {
        width: min(calc(100vw - 2rem), 440px);
        border: 0;
        border-radius: 24px;
        padding: 0;
        background: var(--surface);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.58);
        backdrop-filter: blur(6px);
      }

      .dialog-content {
        padding: 1.5rem;
      }

      .warning-icon {
        display: grid;
        width: 48px;
        height: 48px;
        margin-bottom: 1rem;
        place-items: center;
        border-radius: 50%;
        background: #fee4e2;
        color: var(--danger);
        font-size: 1.35rem;
        font-weight: 800;
      }

      .dialog-content h2 {
        margin-bottom: 0.5rem;
        font-size: 1.35rem;
      }

      .dialog-actions {
        justify-content: flex-end;
        margin-top: 1.5rem;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        font-weight: 700;
        color: var(--danger-dark);
      }

      @media (max-width: 560px) {
        main {
          width: min(100% - 1rem, 720px);
        }

        .content,
        .dialog-content {
          padding: 1.15rem;
        }

        .actions button,
        .dialog-actions button {
          width: 100%;
        }
      }
    </style>
